class Stack:
    def __init__(self):
        self.stack = []

    # 如果堆栈为空，则返回True
    def is_empty(self):
        return len(self.stack) == 0

    def push(self, item):
        self.stack.append(item)

    def pop(self):
        if not stack1.is_empty():
            self.stack.pop()



    def peek(self):
        if not stack1.is_empty():
            return self.stack[-1]

    def print_stack(self, message):
        print(f"{message}: {self.stack}")

stack1 = Stack()

# 将元素添加到堆栈
stack1.push(5)
stack1.push(100)
stack1.push(1000)

# 打印堆栈
stack1.print_stack("Stack after pushing 2 items")


# 查找堆栈
print(f"Peek the stack: {stack1.peek()}")


# 查找后的堆栈
stack1.print_stack("Stack after peeking")

# 弹出堆栈
stack1.pop()

stack1.print_stack("After popping")

